// 格子按行优先排列 damage=-1 表示通配 id=0 表示空

/// (id, count, damage)
pub type RawStack = (i16, u8, i16);
/// (id, damage) 空格为 (0, 0) 通配 damage 为 -1
pub type RawCell = (i16, i16);

#[derive(Debug, Clone, Copy)]
pub struct RawShaped {
    pub width: u8,
    pub height: u8,
    pub result: RawStack,
    pub cells: &'static [RawCell],
}

#[derive(Debug, Clone, Copy)]
pub struct RawShapeless {
    pub result: RawStack,
    pub ingredients: &'static [RawCell],
}

#[derive(Debug, Clone, Copy)]
pub struct RawFurnace {
    pub input: RawCell,
    pub result: RawStack,
}

